c=concept(1034,'Activation functions and differentiability','Step is nonlinear already; sigmoid/tanh are smooth alternatives, with distinct zero values and saturation limits.')
ask(c,'Why is a hard step activation unsuitable for ordinary gradient-based backpropagation even though it is nonlinear?', ['Its derivative is zero away from the threshold and undefined at the threshold','It is a linear function with constant slope1','It has the same nonzero derivative as sigmoid everywhere','It cannot produce binary outputs'],['The obstacle is the lack of a useful ordinary gradient, not absence of nonlinearity.','A step is not linear and has no such derivative.','Sigmoid is smooth with a positive derivative at finite inputs, unlike a step.','Binary output is exactly its purpose.'],conflict=(1034,'The transition from step to MLP activations suggests nonlinearity must first be introduced.','The step already violates linearity; smooth/useful derivatives are the relevant distinction for ordinary backpropagation.'))
ask(c,'At zero input, what are step(0), sigmoid(0) and tanh(0), using the slide’s step convention?', ['1,0.5,0','0,0.5,0','1,0,0.5','0.5,1,0'],['Equality fires the step; sigmoid is1/(1+1); tanh has zero numerator.','This changes the inclusive step convention.','This exchanges sigmoid and tanh values.','A binary step does not output0.5.'],kind='numerical',steps=['Use z>=0 for step.','Evaluate exp(0)=1 in both smooth formulas.'],formula=[sig,fm('tanh(z)=(exp(z)-exp(-z))/(exp(z)+exp(-z))',{'z':'real input'},{'all':'dimensionless'})],locator='Three activation formulas and curves')
ask(c,'Which activation is odd and zero-centered?', ['tanh','Logistic sigmoid','The inclusive binary step','Softmax probability of one arbitrary class'],['tanh(-z)=-tanh(z) and tanh(0)=0.','Sigmoid(-z)=1-sigmoid(z), not its negative.','The binary step is not odd.','A nonnegative class probability is not generally an odd scalar function.'],locator='Tanh curve and formula')
ask(c,'If every hidden activation were the identity, what would composing fully connected affine layers yield?', ['Another affine map, so depth alone would not create nonlinear decision features','A nonlinear map merely because several matrix products are used','A constant map regardless of the weights','A softmax distribution even without an output normalization'],['Compositions W2(W1x+b1)+b2 remain affine in x.','Matrix multiplication and addition preserve affine form.','Nonzero weights can preserve input dependence.','No probability normalization appears automatically.'],kind='synthesis',pages=[1034,1038,1039],formula=[fm('W2*(W1*x+b1)+b2=(W2*W1)*x+(W2*b1+b2)',{'x':'input vector','W1,W2':'compatible weight matrices','b1,b2':'compatible bias vectors'},{'all':'dimensionless'},['Identity activations; compatible matrix shapes.'])],locator='Need for nonlinear activations and multilayer equations')
issue(1034,'step-nonlinearity','Step-to-MLP discussion conflates nonlinearity with gradient suitability.','State step is nonlinear; explain zero/undefined ordinary derivative.')
c=concept(1035,'Activation ranges and softmax','Finite open ranges, zero centering, class-normalized probabilities and two-class equivalence.')
soft=fm('p_i=exp(z_i)/sum(j=1..K) exp(z_j)',{'z_i':'logit for class i','p_i':'probability of class i','K':'number of mutually exclusive classes','j':'class summation index'},{'all':'dimensionless'},['Finite logits; K positive; probabilities normalized over classes.'])
ask(c,'For finite real input and exact arithmetic, which ranges are correct despite the closed brackets printed in the table?', ['Sigmoid:(0,1); tanh:(-1,1)','Sigmoid:[0,1]; tanh:[-1,1], with endpoints attained at finite inputs','Sigmoid:(-1,1); tanh:(0,1)','Sigmoid:[0,infinity); tanh:all real values'],['The endpoints are asymptotic limits, not attained finite-input outputs.','Finite exponentials keep sigmoid strictly between0 and1 and tanh strictly between-1 and1.','This exchanges their ranges.','These resemble ReLU and leaky-ReLU ranges, not sigmoid/tanh.'],assumptions=['Ignore floating-point saturation caused by rounding.'],citekind='table',locator='Range column',conflict=(1035,'The table prints closed sigmoid and tanh intervals.','Distinguish finite real ranges from their closures and limiting values.'))
ask(c,'For mutually exclusive classes with logits(0,ln2,ln3), what does softmax return?', ['(1/6,2/6,3/6)','(0,ln2,ln3)','(1/3,1/3,1/3)','(1/2,2/3,3/4)'],['Exponentials are1,2,3 and the denominator is6.','These are the unnormalized logits.','Uniform probabilities require equal logits.','These are separate sigmoid values, not a normalized softmax.'],kind='numerical',steps=['Exponentiate each logit to get1,2,3.','Divide by their sum6.'],formula=[soft],assumptions=['Natural logarithms.'],locator='Softmax expression')
ask(c,'What happens to softmax probabilities if the same finite constant is added to every logit?', ['They are unchanged','Every probability increases by that constant','Only the highest-logit probability changes','They become uniform regardless of the original logits'],['The common exponential factor cancels between numerator and denominator.','Probabilities do not shift additively with logits.','Every ratio keeps the same value.','Relative logit differences remain unchanged.'],formula=[soft],locator='Softmax normalization')
ask(c,'With two classes, softmax probability for class1 is equivalent to which sigmoid expression?', ['sigmoid(z1-z2)','sigmoid(z1+z2)','sigmoid(z1)*sigmoid(z2)','sigmoid(z2-z1)'],['Divide numerator and denominator by exp(z1), giving1/(1+exp(z2-z1)).','The sum does not determine the relative class probability.','Multiplying two sigmoids does not impose the two-class normalization.','This is the complementary class probability.'],formula=[soft,sig],assumptions=['Two mutually exclusive classes; finite logits.'],locator='Softmax and binary/multiclass discussion',conflict=(1035,'The wording suggests softmax is specially required whenever classes>=2.','Two-class softmax is valid and equivalent to a sigmoid of a logit difference; binary already means two classes.'))
ask(c,'Which output choice fits three independent yes/no object attributes rather than one of three mutually exclusive classes?', ['Three sigmoids, without forcing their sum to1','A single three-class softmax that forces exactly one attribute to win','One sigmoid with no encoding of which attribute it represents','A hard threshold on the sum of all labels only'],['Independent attributes may co-occur, so each needs its own probability.','That normalization wrongly makes co-occurring attributes compete.','One scalar cannot directly represent three independent probabilities.','Summing discards the individual attribute identities.'],kind='scenario',assumptions=['The three attributes may all be present or absent independently; this is a supplied interpretation variant.'],pages=[1035,1039],locator='Binary/multiclass output formatting')
ask(c,'What is the defensible benefit of tanh being zero-centered?', ['It can provide signed hidden activations, but does not guarantee better training for every problem','It prevents saturation for arbitrarily large input magnitude','It guarantees all network gradients have magnitude1','It makes a bias term mathematically unnecessary in every layer'],['Zero centering is a property that may help optimization, not a universal superiority theorem.','Tanh saturates toward±1.','Its derivative varies and approaches0 in saturated regions.','Signed activation does not replace every learned offset.'],citekind='table',locator='Tanh better-than-sigmoid explanation')
issue(1035,'range-and-class-scope','Closed activation ranges and classes>=2 softmax wording need qualifications.','Use open finite ranges, limit closures, two-class equivalence and mutually-exclusive versus multilabel assumptions.')
c=concept(1036,'Vanishing gradients','Activation derivatives and weight Jacobians jointly govern backpropagation; sigmoid and tanh maxima differ.')
ask(c,'What are the maximum scalar derivatives of logistic sigmoid and tanh over real input?', ['1/4 and1, respectively','1/4 and1/4, respectively','1 and1, respectively','1 and1/4, respectively'],['Sigmoid derivative s(1-s) peaks at s=1/2; tanh derivative1-tanh²(z) peaks at z=0.','The shared0.25 example is not the tanh maximum.','The sigmoid maximum is only1/4.','This reverses the two maxima.'],formula=[sig,fm('tanh\u2032(z)=1-tanh(z)^2',{'z':'real input','tanh':'hyperbolic tangent'},{'all':'dimensionless'})],conflict=(1036,'The source groups sigmoid/tanh with a small maximum derivative example0.25.','Differentiate the displayed functions: sigmoid maximum1/4, tanh maximum1.'))
ask(c,'Consider only four sigmoid derivative factors, each at its maximum, and set intervening scalar weights to1. What is their product?', ['1/256','1/4','1/16','4'],['(1/4)^4=1/256.','This counts only one factor.','This counts two factors.','This adds/inverts factors instead of multiplying them.'],kind='numerical',steps=['Each derivative is1/4.','Multiply four factors to obtain1/256.'],formula=[fm('G=(1/4)^L',{'G':'product of activation derivatives','L':'number of sigmoid factors'},{'all':'dimensionless'},['Every factor at sigmoid maximum; intervening scalar weights1.'])],locator='Gradient multiplication explanation')
ask(c,'Why does multiplying sigmoid derivative bounds alone not establish the full gradient magnitude in an arbitrary deep network?', ['Backpropagation also multiplies weight matrices and sums paths, which can amplify or attenuate the signal','Weight matrices are never used in backpropagation','Every weight is constrained to1 by the sigmoid definition','A small activation derivative makes every possible network gradient exactly zero'],['Full Jacobian products include learned weights, not just activation factors.','The chain rule includes those matrices.','Sigmoid imposes no such weight constraint.','Small nonzero factors need not yield exactly zero, and other factors matter.'],locator='Gradients multiplied through layers',conflict=(1036,'Small activation gradients are used to broadly characterize all deep-network gradients.','Scope the activation-only product and identify the omitted weight-Jacobian factors.'))
ask(c,'What is the practical consequence of very small gradients in early layers?', ['Their parameter updates can become very slow for a fixed learning rate','Their gradients must reverse sign every iteration','The forward predictions become undefined','Only the output-layer labels are erased'],['Small gradients yield small descent steps and can impede early-layer learning.','Vanishing magnitude does not imply sign alternation.','Forward computation may remain perfectly defined.','Labels are data, not erased by small derivatives.'],locator='Initial layers learn slowly explanation')
issue(1036,'derivative-maxima','A shared0.25 maximum is inappropriate for tanh; activation-only products omit weights.','Derive maxima and bound only the explicitly scoped product.')
c=concept(1037,'ReLU, leaky ReLU and GELU','Piecewise values/derivatives, dead-unit mitigation, approximate GELU lower bound and Gaussian-CDF definition.')
relu=fm('ReLU(z)=max(0,z); Leaky(z)=max(0.01*z,z)',{'z':'real input','ReLU':'rectified linear activation','Leaky':'leaky ReLU with negative slope0.01'},{'all':'dimensionless'},['Derivative at zero requires a separately supplied computational convention.'])
ask(c,'At z=-2, what are ReLU(z) and the slide’s leaky-ReLU(z)?', ['0 and-0.02','-2 and-0.02','0 and+0.02','-0.02 and0'],['ReLU clips the negative input; the leaky branch multiplies it by0.01.','ReLU does not preserve a negative input.','The leaky output retains the negative sign.','This exchanges the two functions.'],kind='numerical',steps=['max(0,-2)=0.','max(-0.02,-2)=-0.02.'],formula=[relu],citekind='table',locator='ReLU and LeakyReLU formula rows')
ask(c,'Which derivative pair applies at strictly negative input for these two functions?', ['ReLU:0; leaky ReLU:0.01','ReLU:1; leaky ReLU:0.01','ReLU:0; leaky ReLU:1','ReLU:-1; leaky ReLU:-0.01'],['The inactive ReLU branch is constant; the leaky branch has slope0.01.','ReLU slope1 applies to positive inputs.','The leaky positive branch has slope1.','Negative input does not imply negative derivative.'],formula=[relu],citekind='table',locator='Positive/negative branches')
ask(c,'At exactly z=0, what mathematical qualification is needed for ReLU and this leaky ReLU?', ['Neither has a unique ordinary derivative there; a software gradient convention must be stated','Both are discontinuous there','Both have derivative1/2 by ordinary differentiation','Both have a unique derivative0 because their output is0'],['The left and right slopes differ even though the functions are continuous.','The function values match from both sides.','An average slope is a possible convention, not the ordinary derivative.','Function value0 does not imply derivative0.'],formula=[relu],citekind='table',locator='Piecewise formulas and origin of curves')
ask(c,'What is the specific benefit of the nonzero negative slope in leaky ReLU?', ['It permits a local gradient through negative preactivations, reducing the fully inactive-unit problem','It guarantees the entire network gradient can never vanish','It forces all negative outputs to become positive','It guarantees convergence to the global optimum'],['Unlike zero-slope ReLU, the negative branch retains a nonzero local derivative.','Other layers, weights and losses still affect gradient flow.','The negative branch remains negative for negative input.','A local activation property is not a global optimization guarantee.'],citekind='table',locator='Prevents dying ReLU wording')
ask(c,'The slide writes GELU(z)=z*Phi(z). If Phi is the standard normal cumulative distribution function, which statement follows for finite z<0?', ['GELU(z) is negative because0<Phi(z)<1','GELU(z) equals0 for every negative input','GELU(z) is positive because Phi is positive','GELU(z) equals z exactly for all finite negative inputs'],['A negative number multiplied by a strictly positive probability is negative.','That is ReLU’s negative branch, not GELU.','The negative input retains its sign in the product.','Phi is not identically1.'],formula=[fm('GELU(z)=z*Phi(z)',{'z':'real input','Phi':'standard normal cumulative distribution function'},{'all':'dimensionless'},['Use the exact Gaussian-CDF GELU, not a tanh approximation.'])],citekind='table',locator='GELU formula and negative dip',assumptions=['Phi definition supplied explicitly, consistent with https://arxiv.org/abs/1606.08415.'])
ask(c,'The GELU range row begins at about-0.17. What is the careful interpretation?', ['A rounded negative minimum, not an exact symbolic value or a zero lower bound','Exactly-0.17 is attained by definition for every negative input','The function is nonnegative like ReLU','The minimum equals-1 because the input can be-1'],['The smooth curve has a small negative minimum; numerical minimization gives approximately-0.16997.','GELU varies continuously and does not have that constant branch.','The plot visibly dips below0.','The output is z times a CDF, not generally z.'],citekind='table',locator='GELU range and plotted dip',conflict=(1037,'GELU lower bound is printed as-0.17 without approximation qualification.','Treat the value as rounded; exact Gaussian-CDF GELU minimum can be computed from Phi(z)+z*phi(z)=0.'))
ask(c,'For a strictly positive input, which comparison is correct?', ['ReLU and leaky ReLU equal the input; exact GELU is strictly between0 and the input','All three equal the input exactly at every positive value','GELU always exceeds the input','Leaky ReLU multiplies positive input by0.01'],['Both piecewise functions use their identity branch, while0<Phi(z)<1 for finite z.','GELU only approaches the identity asymptotically.','Multiplication by a CDF below1 reduces a positive input.','The0.01 branch is for negative input.'],citekind='table',locator='Three formula rows',assumptions=['Finite strictly positive input; exact Gaussian-CDF GELU.'])
issue(1037,'gelu-and-mitigation','Phi undefined; GELU minimum rounded; activation benefits expressed too absolutely.','Supply standard normal CDF definition, mark approximate minimum, and distinguish local gradient properties from global guarantees.')
