c=concept(1043,'Cross-entropy sign, indexing and MSE','As-printed log-likelihood versus repaired minimization loss; softmax is not cross-entropy; numerical examples and units.')
bce=fm('L=-[y*ln(p)+(1-y)*ln(1-p)]',{'L':'single-example binary cross-entropy','y':'target in{0,1}','p':'predicted probability of class1'},{'all':'dimensionless'},['0<p<1; natural logarithm; loss is minimized.'])
cce=fm('L=-(1/n)*sum_i sum_j y_ij*ln(p_ij)',{'L':'mean categorical cross-entropy','n':'positive number of examples','j':'class index1..K','K':'number of mutually exclusive classes','y_ij':'one-hot target indicator','p_ij':'predicted class probability'},{'all':'dimensionless'},['Positive probabilities normalized over classes; natural logarithm.'])
mse=fm('MSE=(1/n)*sum_i (y_i-yhat_i)^2',{'n':'positive number of examples','y_i':'target','yhat_i':'prediction','MSE':'mean squared error'},{'y_i,yhat_i':'specified common target unit U','MSE':'U²'},['Targets and predictions use the same units.'])
ask(c,'For y=1 and p=1/2, what do the slide’s printed binary expression and the explicitly repaired cross-entropy equal?', ['Printed:-ln2; repaired:+ln2','Printed:+ln2; repaired:-ln2','Both:+ln2','Both:0'],['The printed expression is ln(1/2)=-ln2; the minimization loss adds the missing minus sign.','This reverses printed and repaired signs.','The printed formula visibly lacks the leading minus.','A probability of one-half is not a perfect prediction of a known positive label.'],kind='numerical',steps=['Set y1, so only ln(p) remains in the printed expression.','Compute ln(1/2)=-ln2; negate for standard cross-entropy.'],formula=[bce],conflict=(1043,'The binary cross-entropy formula has no leading minus sign.','Separate the exact printed log-likelihood from the explicitly corrected minimized negative log-likelihood.'),locator='Binary formula')
ask(c,'Why would minimizing the printed no-minus expression be the wrong direction for a known positive label?', ['It rewards reducing the predicted probability of that label toward0','It is identical to minimizing negative log-likelihood','It always equals zero regardless of prediction','It changes the class label from1 to0 automatically'],['For y1, ln(p) decreases without bound as p approaches0, worsening the true-class prediction.','Changing the sign reverses the optimization direction.','The logarithm varies with p.','The expression evaluates a label; it does not rewrite it.'],formula=[bce],conflict=(1043,'The printed log-likelihood is called a loss without changing its sign.','Analyze monotonicity of ln(p) for a positive example and contrast minimization with maximization.'),locator='Binary expression')
ask(c,'For one example with target class2 and probabilities(0.2,0.5,0.3), what is the repaired categorical cross-entropy?', ['ln2','ln5','ln(10/3)','-ln2'],['The one-hot target selects only-log(0.5)=ln2.','This uses class1’s probability.','This uses class3’s probability.','This keeps the source’s missing-minus sign.'],kind='numerical',steps=['Select the true class2 probability0.5.','Compute-ln(0.5)=ln2.'],formula=[cce],assumptions=['One-hot labels; natural logarithm.'],conflict=(1043,'The multiclass formula also lacks a leading minus sign.','Apply the explicitly corrected negative log-likelihood, selecting the true class.'),locator='Multiclass formula')
ask(c,'Which statement correctly separates softmax from categorical cross-entropy?', ['Softmax maps logits to probabilities; cross-entropy compares those probabilities with target labels','Softmax is the negative logarithm of the target probability itself','Cross-entropy maps logits to a probability vector without needing labels','They are identical functions with interchangeable inputs and outputs'],['The activation and loss have different roles even when used together.','That describes a one-hot cross-entropy term, not softmax normalization.','A target-dependent comparison is different from probability normalization.','Their domains and purposes are distinct.'],pages=[1035,1043],conflict=(1043,'The multiclass logarithmic loss is called generally known as Softmax.','Compare the probability-normalization formula onp1035 with the target-dependent loss onp1043.'),locator='Softmax label beside multiclass loss')
ask(c,'Two regression examples have targets(1,3) and predictions(2,1), all in meters. What are their MSE and its units?', ['2.5 m²','5 m²','2.5 m','1.5 m²'],['Squared errors are1 and4; their mean is2.5 with squared length units.','This is the sum, not the mean.','Squaring residuals squares the unit.','This averages absolute errors rather than squared errors.'],kind='numerical',steps=['Residuals are-1m and2m.','Square to1m² and4m².','Average to2.5m².'],formula=[mse],locator='MSE formula')
ask(c,'In the categorical formula, which interpretation of the two indices is correct?', ['i selects an example and j selects a class','i selects a class and j selects an epoch','Both indices select hidden layers','Both indices select repeated copies of one probability'],['The outer average runs over examples and the inner sum over classes.','This exchanges roles and introduces an absent epoch index.','The loss is indexed by data and class, not layers.','The probabilities and target indicators vary by example and class.'],formula=[cce],locator='i,j,K definitions')
