grad=fm('e=yhat-y; dL/dw=e*x; dL/db=e',{'e':'prediction-minus-target residual','yhat':'prediction w*x+b','y':'target','w':'weight','x':'input','b':'bias','L':'0.5*(yhat-y)^2'},{'all':'dimensionless normalized numerical coordinates'},['Single example; identity activation.'])
ask(c,'For half-squared error and yhat=w*x+b, which gradient pair is correct?', ['dL/dw=(yhat-y)*x; dL/db=yhat-y','dL/dw=(y-yhat)*x; dL/db=y-yhat','dL/dw=yhat-y; dL/db=(yhat-y)*x','dL/dw=2*(yhat-y)*x; dL/db=2*(yhat-y)'],['Chain rule multiplies the residual by x for the weight and by1 for the bias.','This reverses the gradient sign.','This exchanges the local derivatives with respect to weight and bias.','Those factors2 belong to unhalved squared error.'],formula=[half,grad],locator='Chain-rule derivation')
ask(c,'A supplied linear example has x=-2 and prediction-minus-target residual e=3. What are dL/dw and dL/db?', ['-6 and3','6 and-3','3 and-6','-12 and6'],['The weight gradient is3*(-2)=-6; the bias gradient is3.','This reverses both signs.','This exchanges weight and bias factors.','This adds the factor2 from an unhalved loss.'],kind='numerical',steps=['Use e*x for the weight.','Use e for the bias.'],formula=[grad],assumptions=unit,locator='Weight and bias gradient formulas')
ask(c,'If x=0 but prediction differs from target, what happens to the two linear-model gradients?', ['The weight gradient is0; the bias gradient may be nonzero','Both gradients must be0','Only the weight gradient may be nonzero','Both gradients equal the learning rate'],['The weight derivative includes x, whereas the bias derivative includes1.','A nonzero residual can still update the bias.','The situation is the reverse.','The learning rate scales updates, not the loss derivative itself.'],formula=[grad],locator='dyhat/dw=x and dyhat/db=1')
ask(c,'For the supplied nonlinear variant yhat=sigmoid(w*x+b) with half-squared error, which extra factor enters both parameter gradients?', ['yhat*(1-yhat)','1/yhat','w+b','The class count K'],['The chain rule includes the sigmoid derivative at the preactivation.','That resembles a logarithmic derivative, not sigmoid’s derivative.','The activation derivative is not the sum of parameters.','No multiclass softmax is specified.'],formula=[half,sig,fm('dL/dw=(yhat-y)*yhat*(1-yhat)*x; dL/db=(yhat-y)*yhat*(1-yhat)',{'L':'half-squared error','yhat':'sigmoid(w*x+b)','y':'target','w':'weight','x':'input','b':'bias'},{'all':'dimensionless'},['Supplied sigmoid-output variant, not the slide’s identity-output calculation.'])],pages=[1034,1046],locator='Sigmoid formula and linear chain-rule example')
